<?php declare(strict_types=1); require_once __DIR__.'/../includes/auth.php'; require_auth(); require_once __DIR__.'/../includes/csrf.php'; require_once __DIR__.'/../config/database.php';$tracking=substr(trim((string)($_GET['tracking']??'')),0,15);$document=document_by_tracking($conn,$tracking);if(!$document){flash('error','Document not found.');redirect('dashboard.php');}$users=$conn->query("SELECT id,fname,mname,lname,designation,department FROM dr_users WHERE status <> 'Inactive' ORDER BY department,lname,fname")->fetch_all(MYSQLI_ASSOC);$page_title='Forward document';$page_heading='Forward '.$tracking;require __DIR__.'/../includes/app-shell.php'; ?>
<section class="panel"><form method="post" action="<?= url('actions/forward-document.php') ?>" class="form-grid"><?= csrf_input() ?><input type="hidden" name="tracking" value="<?= e($tracking) ?>"><div class="field"><label for="receiver_id">Forward to</label><select id="receiver_id" name="receiver_id" required><option value="">Select a recipient</option><?php foreach($users as $recipient): if((int)$recipient['id']===(int)$_SESSION['user_id'])continue; ?><option value="<?= $recipient['id'] ?>"><?= e($recipient['department'].' — '.user_name($recipient).' ('.$recipient['designation'].')') ?></option><?php endforeach; ?></select></div><div class="field"><label for="title">Document title</label><input id="title" name="title" value="<?= e($document['title']) ?>" minlength="4" maxlength="50" required></div><div class="field field-full"><label for="remarks">Forwarding remarks</label><textarea id="remarks" name="remarks" maxlength="500" required></textarea></div><div class="form-actions field-full"><a class="btn btn-secondary" href="<?= url('documents/view.php?tracking='.rawurlencode($tracking)) ?>">Cancel</a><button class="btn" type="submit">Forward document</button></div></form></section><?php require __DIR__.'/../includes/footer.php'; ?>
